import { backendClient } from './client'

export const backendAdminService = {
  async updateBranding(tenantId: string, branding: Record<string, unknown>): Promise<void> {
    await backendClient.fetch('/admin/branding', {
      method: 'PUT',
      body: JSON.stringify({ tenantId, branding }),
    })
  },

  async updateLocalization(tenantId: string, localization: Record<string, unknown>): Promise<void> {
    await backendClient.fetch('/admin/localization', {
      method: 'PUT',
      body: JSON.stringify({ tenantId, localization }),
    })
  },

  async getAnalytics(tenantId: string): Promise<Record<string, unknown>> {
    return backendClient.fetch(`/admin/analytics?tenantId=${tenantId}`)
  },
}
